ALTER TABLE "delivery"."pathao_booking" ADD COLUMN "reconciliation_fingerprint" text;--> statement-breakpoint
ALTER TABLE "delivery"."pathao_booking" ADD COLUMN "reconciliation_reason" text;--> statement-breakpoint
ALTER TABLE "delivery"."pathao_booking" ADD COLUMN "reconciled_by" text;--> statement-breakpoint
ALTER TABLE "delivery"."pathao_booking" ADD COLUMN "reconciled_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "delivery"."pathao_booking" ADD COLUMN "last_error_code" text;--> statement-breakpoint
ALTER TABLE "delivery"."pathao_webhook_inbox" ADD COLUMN "processing_lease_owner" uuid;--> statement-breakpoint
UPDATE "delivery"."pathao_webhook_inbox" SET "processing_state" = 'retry', "next_attempt_at" = clock_timestamp(), "processing_lease_expires_at" = NULL WHERE "processing_state" = 'processing' AND "processing_lease_expires_at" IS NULL;--> statement-breakpoint
UPDATE "delivery"."pathao_webhook_inbox" SET "processing_lease_owner" = gen_random_uuid() WHERE "processing_state" = 'processing' AND "processing_lease_owner" IS NULL;--> statement-breakpoint
ALTER TABLE "delivery"."pathao_booking" ADD CONSTRAINT "pathao_booking_reconciled_by_user_id_fk" FOREIGN KEY ("reconciled_by") REFERENCES "identity"."user"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "pathao_booking_reconciliation_command_uidx" ON "delivery"."pathao_booking" USING btree ("reconciliation_command_id");--> statement-breakpoint
CREATE INDEX "pathao_webhook_processing_lease_idx" ON "delivery"."pathao_webhook_inbox" USING btree ("processing_lease_expires_at","id") WHERE "delivery"."pathao_webhook_inbox"."processing_state" = 'processing';--> statement-breakpoint
ALTER TABLE "delivery"."pathao_booking" ADD CONSTRAINT "pathao_booking_source_check" CHECK ("delivery"."pathao_booking"."source" in ('api', 'manual'));--> statement-breakpoint
ALTER TABLE "delivery"."pathao_booking" ADD CONSTRAINT "pathao_booking_reconciliation_pair_check" CHECK (("delivery"."pathao_booking"."reconciliation_command_id" is null and "delivery"."pathao_booking"."reconciliation_fingerprint" is null and "delivery"."pathao_booking"."reconciliation_reason" is null and "delivery"."pathao_booking"."reconciled_by" is null and "delivery"."pathao_booking"."reconciled_at" is null) or ("delivery"."pathao_booking"."reconciliation_command_id" is not null and "delivery"."pathao_booking"."reconciliation_fingerprint" is not null and "delivery"."pathao_booking"."reconciliation_fingerprint" ~ '^[0-9a-f]{64}$' and "delivery"."pathao_booking"."reconciliation_reason" is not null and length("delivery"."pathao_booking"."reconciliation_reason") between 3 and 500 and "delivery"."pathao_booking"."reconciled_by" is not null and "delivery"."pathao_booking"."reconciled_at" is not null));--> statement-breakpoint
ALTER TABLE "delivery"."pathao_booking" ADD CONSTRAINT "pathao_booking_reconciliation_fingerprint_check" CHECK ("delivery"."pathao_booking"."reconciliation_fingerprint" is null or "delivery"."pathao_booking"."reconciliation_fingerprint" ~ '^[0-9a-f]{64}$');--> statement-breakpoint
ALTER TABLE "delivery"."pathao_booking" ADD CONSTRAINT "pathao_booking_last_error_code_check" CHECK ("delivery"."pathao_booking"."last_error_code" is null or "delivery"."pathao_booking"."last_error_code" ~ '^PATHAO_[A-Z0-9_]+$');--> statement-breakpoint
ALTER TABLE "delivery"."pathao_webhook_inbox" ADD CONSTRAINT "pathao_webhook_processing_lease_pair_check" CHECK (("delivery"."pathao_webhook_inbox"."processing_state" = 'processing' and "delivery"."pathao_webhook_inbox"."processing_lease_owner" is not null and "delivery"."pathao_webhook_inbox"."processing_lease_expires_at" is not null) or ("delivery"."pathao_webhook_inbox"."processing_state" <> 'processing' and "delivery"."pathao_webhook_inbox"."processing_lease_owner" is null and "delivery"."pathao_webhook_inbox"."processing_lease_expires_at" is null));
